		message: { role: "user", content: [{ type: "text", text }], timestamp: 100 },
		parentId: "root",
		timestamp: 100,
	} as any as SessionEntry;
}

function compactionEntry(id: string, firstKeptEntryId: string): SessionEntry {
	return {
		id,
		type: "compaction",
